{{-- Sample of the certificate of completion, for students who don't have their own yet (Your account → Online Course). --}}
<div class="mt-6 flex flex-wrap items-start gap-4 rounded-[var(--radius-control)] border border-gold-500 bg-gold-50 p-4">
    <a href="/images/course-certificate-sample.jpg" target="_blank" rel="noopener" title="Open the sample certificate">
        <picture><source type="image/webp" srcset="/images/course-certificate-sample.webp"><img src="/images/course-certificate-sample.jpg" alt="Sample certificate of completion for the online course" width="260" height="170" loading="lazy" class="rounded border border-steel-300 bg-white" style="width:16.25rem;height:auto"></picture>
    </a>
    <div class="min-w-0 flex-1" style="min-width:13rem">
        <p class="font-semibold text-steel-950">🎓 Your certificate of completion (sample)</p>
        <p class="mt-1 text-sm text-steel-800">This is what your certificate will look like, with your name, the date you completed the course and your own certificate number (CTN).</p>
        <p class="mt-2 text-sm"><a href="/images/course-certificate-sample.jpg" target="_blank" rel="noopener" class="font-semibold underline">View the sample bigger</a></p>
    </div>
</div>
